SELECT T1.TOTLE_TRADE_ID totalTradeId, T1.TRADE_DATE tradeDate, T1.SETTLE_DATE settleDate, T1.FINPROD_ID finprodId, T2.FINPROD_ABBR finprodAbbr, T1.FINPROD_TYPE2 finprodType2, T1.PS ps, T1.SHARE_AMT/100 settleNumT, T1.TRADE_AMT settleAmtT, case when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus01} THEN #{cleanStatus01} when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus02} THEN #{cleanStatus02} when T9.PS = #{feePs02} and (T9.SETTLE_STATUS is null or T9.SETTLE_STATUS = #{settlementStatus02}) and T9.ORDER_RET_STATUS = '03' THEN #{cleanStatus03} ELSE NULL END cleanStatus, T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.SEC_MANAGE_ACCT_ID secAcctId, T8.SETTLE_SEQ_NO settleSeqNo, T1.TG_BUSI_TYPE tgBusiType, T3.TRADE_ID tradeId, case when T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F03} and T1.PS = #{PS_T07} then null else T1.SHARE_AMT / 100 end settleNum, T3.TRADE_AMT settleAmt, T4.PORTFOLIO_ID portfolioId, T1.CCY ccy, T1.COUNTER_ID counterId, btm.busi_type busiType FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD T4 ON T3.TRADE_ID = T4.TRADE_ID left join FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE on FIN_PRODUCT_TYPE.FINPROD_ID=T3.FINPROD_ID LEFT JOIN TRD_BANK_MANUAL_SETTLE_INFO T8 ON T1.TOTLE_TRADE_ID = T8.TRADE_ID LEFT JOIN STL_PAY_ORDERS T9 ON T3.TRADE_ID = T9.TRADE_ID LEFT JOIN INF_PAY_ORDERS_STATUS T10 ON T9.ORDER_ID = T10.ORDER_ID LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='PINAN_ASSET_TYPE' and sdl1.item_code = FIN_PRODUCT_TYPE.TYPE_8 LEFT JOIN FIN_PRODUCT_ISSUE fpi ON T1.FINPROD_ID = fpi.FINPROD_ID LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg, INPUT_VALUE_2 as ps, INPUT_VALUE_3 as issueClass, OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE = 'BUSI_TYPE_MAPPING') btm ON FIN_PRODUCT_TYPE.TYPE_8 = btm.Finprod_Type_Tg AND T1.Ps = btm.ps AND ((T2.FINPROD_TYPE2 = 'F32' and btm.issueClass = fpi.ISSUE_CLASS) or (T2.FINPROD_TYPE2 != 'F32' or T2.FINPROD_TYPE2 is null) and btm.issueClass is null) LEFT JOIN (select pm.STATUS status, pm.BUSINESS_DATA_PK1 pk1 from SYS_DATA_PROCESS_MARK pm inner join (select max(HIS_NO) HIS_NO, WORKFLOW_ID from SYS_DATA_PROCESS_MARK where 1=1
AND PAGE_ID in (#{pageId},#{pageId01})
group by WORKFLOW_ID) tempHis on pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID where pm.status in ('A', 'U', 'P') order by pm.create_time desc) sdpm ON sdpm.pk1 = T1.Totle_Trade_Id WHERE (T8.SETTLE_SEQ_NO IS NULL OR T8.SETTLE_STATUS = #{DELIVERY_STATUS_01})
AND T1.TG_BUSI_TYPE IN(
#{item}
)
AND T1.TRADE_STATUS =#{TRADE_STATUS_01} AND T1.Is_Cancel =#{isCalcN} AND T1.SETTLE_DATE = #{batchDate} and sdpm.status is null
AND ( T1.TRADE_MARKET in( #{tradePlat_01},#{tradePlat_02} ) or T1.TRADE_MARKET is null )
AND T1.FINPROD_TYPE2 not IN (
#{item}
)
union all SELECT T1.TOTLE_TRADE_ID totalTradeId, T1.TRADE_DATE tradeDate, T1.SETTLE_DATE settleDate, T1.FINPROD_ID finprodId, T2.FINPROD_ABBR finprodAbbr, T1.FINPROD_TYPE2 finprodType2, T1.PS ps, T1.SHARE_AMT/100 settleNumT, T1.TRADE_AMT settleAmtT, case when btm.busi_type='06' then #{cleanStatus01} else null end cleanStatus, T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.SEC_MANAGE_ACCT_ID secAcctId, T8.SETTLE_SEQ_NO settleSeqNo, T1.TG_BUSI_TYPE tgBusiType, T3.TRADE_ID tradeId, case when T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F03} and T1.PS = #{PS_T07} then null else T1.SHARE_AMT / 100 end settleNum, T3.TRADE_AMT settleAmt, T4.PORTFOLIO_ID portfolioId, T1.CCY ccy, T1.COUNTER_ID counterId, btm.busi_type busiType FROM TRD_PRODUCT_TEMP_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN TRD_PRODUCT_TEMP_DEAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_TEMP_DEAL_ADD T4 ON T3.TRADE_ID = T4.TRADE_ID left join FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE on FIN_PRODUCT_TYPE.FINPROD_ID=T3.FINPROD_ID LEFT JOIN TRD_BANK_MANUAL_SETTLE_INFO T8 ON T1.TOTLE_TRADE_ID = T8.TRADE_ID LEFT JOIN STL_PAY_TEMP_ORDERS T9 ON T3.TRADE_ID = T9.TRADE_ID LEFT JOIN INF_PAY_ORDERS_STATUS T10 ON T9.ORDER_ID = T10.ORDER_ID LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='PINAN_ASSET_TYPE' and sdl1.item_code = FIN_PRODUCT_TYPE.TYPE_8 LEFT JOIN FIN_PRODUCT_ISSUE fpi ON T1.FINPROD_ID = fpi.FINPROD_ID LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg, INPUT_VALUE_2 as ps, INPUT_VALUE_3 as issueClass, OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE = 'BUSI_TYPE_MAPPING') btm ON FIN_PRODUCT_TYPE.TYPE_8 = btm.Finprod_Type_Tg AND T1.Ps = btm.ps AND ((T2.FINPROD_TYPE2 = 'F32' and btm.issueClass = fpi.ISSUE_CLASS) or (T2.FINPROD_TYPE2 != 'F32' or T2.FINPROD_TYPE2 is null) and btm.issueClass is null) LEFT JOIN (select pm.STATUS status, pm.BUSINESS_DATA_PK1 pk1 from SYS_DATA_PROCESS_MARK pm inner join (select max(HIS_NO) HIS_NO, WORKFLOW_ID from SYS_DATA_PROCESS_MARK where 1=1
AND PAGE_ID in (#{pageId},#{pageId01})
group by WORKFLOW_ID) tempHis on pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID where pm.status in ('A', 'U', 'P') order by pm.create_time desc) sdpm ON sdpm.pk1 = T1.Totle_Trade_Id WHERE (T8.SETTLE_SEQ_NO IS NULL OR T8.SETTLE_STATUS = #{DELIVERY_STATUS_01})
AND T1.TG_BUSI_TYPE IN(
#{item}
)
AND T1.TRADE_STATUS =#{TRADE_STATUS_01} AND T1.Is_Cancel =#{isCalcN} AND T1.SETTLE_DATE = #{batchDate} and sdpm.status is null
AND ( T1.TRADE_MARKET in( #{tradePlat_01},#{tradePlat_02} ) or T1.TRADE_MARKET is null )
AND T1.FINPROD_TYPE2 not IN (
#{item}
)

